<template>
  <form id="campaignForm" @submit="onFormSubmit">
    <Card>
      <CardContent>
        <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div class="flex flex-col gap-4">
            <FormItemWrapper label="Campaign Name" name="name" :is-required="true">
              <template #default="{ slots }">
                <Input id="name" type="text" v-bind="slots.componentField" />
              </template>
            </FormItemWrapper>

            <slot name="project" />

            <FormItemWrapper label="Urgency Level" name="urgency_level" :is-required="true">
              <template #default="{ slots }">
                <KitFormsSelect
                  id="urgency_level"
                  :items="campaignUrgencyOptions"
                  :component-field="slots.componentField"
                />
              </template>
            </FormItemWrapper>

            <FormItemWrapper label="Channel Strategy" name="channel_strategy" :is-required="true">
              <template #default="{ slots }">
                <KitFormsSelect
                  id="channel_strategy"
                  :items="channelStrategyOptions"
                  :component-field="slots.componentField"
                />
              </template>
            </FormItemWrapper>

            <FormItemWrapper label="End Date" name="end_date">
              <template #default="{ slots }">
                <DatePicker
                  id="end_date"
                  class="w-full"
                  button-class="w-full"
                  :model-value="endDateValue"
                  @update:model-value="(val) => slots.setValue(val ? val.toString() : null, false)"
                />
              </template>
            </FormItemWrapper>

            <div class="grid grid-cols-2 gap-4">
              <FormItemWrapper label="Application Target" name="target_application_count">
                <template #default="{ slots }">
                  <Input
                    id="target_application_count"
                    v-maska
                    type="string"
                    inputmode="numeric"
                    data-maska-number-fraction="0"
                    data-maska-number
                    v-bind="slots.componentField"
                  />
                </template>
              </FormItemWrapper>
              <FormItemWrapper label="Assignment Target" name="target_assignment_count">
                <template #default="{ slots }">
                  <Input
                    id="target_assignment_count"
                    v-maska
                    type="string"
                    inputmode="numeric"
                    data-maska-number-fraction="0"
                    data-maska-number
                    v-bind="slots.componentField"
                  />
                </template>
              </FormItemWrapper>
            </div>

            <Alert v-if="plan" data-testid="campaign-plan-summary">
              <InfoIcon class="h-4 w-4" />
              <AlertTitle>What this campaign will do</AlertTitle>
              <AlertDescription class="text-xs">
                <ul class="list-disc pl-4 space-y-1">
                  <li>
                    Contacts up to <strong>{{ plan.peoplePerDay }}</strong>
                    {{ plan.peoplePerDay === 1 ? 'person' : 'people' }} a day.
                  </li>
                  <li>
                    Each person gets {{ plan.touchPhrase }}, which spends
                    <strong>{{ plan.costPerContact }}</strong>
                    of the <strong>{{ plan.dailyMessageCap }}</strong> messages the campaign may send per day.
                  </li>
                  <li>
                    The same person is not contacted again for <strong>{{ plan.intervalHours }} hours</strong>. After
                    <strong>{{ plan.exhaustionThreshold }}</strong> messages they slow to one every
                    <strong>{{ plan.exhaustedIntervalDays }} days</strong>.
                  </li>
                  <li v-html="plan.stopSentence" />
                </ul>
                <p v-if="plan.smsDailyHardCap !== null" class="mt-2">
                  Texts also draw on a system-wide limit of
                  <strong>{{ plan.smsDailyHardCap.toLocaleString() }}</strong>
                  per day shared with every other campaign.
                </p>
                <p class="mt-2">
                  These are ceilings, not a schedule - a day already partly spent by other campaigns leaves less.
                </p>
              </AlertDescription>
            </Alert>
          </div>

          <div class="flex flex-col gap-4">
            <slot name="aside" />

            <FormItemWrapper label="Selling Points" name="selling_points">
              <template #default="{ slots }">
                <Textarea id="selling_points" rows="4" v-bind="slots.componentField" class="resize-none" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper label="Latest News" name="latest_news">
              <template #default="{ slots }">
                <Textarea id="latest_news" rows="3" v-bind="slots.componentField" class="resize-none" />
              </template>
            </FormItemWrapper>

            <FormItemWrapper label="Custom Notes" name="custom_notes">
              <template #default="{ slots }">
                <Textarea id="custom_notes" rows="3" v-bind="slots.componentField" class="resize-none" />
              </template>
            </FormItemWrapper>
          </div>

          <div class="col-span-1 md:col-span-2 flex justify-end">
            <Button type="submit" :loading="isSaving" :disabled="isSubmitDisabled">{{ submitLabel }}</Button>
          </div>
        </div>
      </CardContent>
    </Card>

    <NavigationGuard
      v-if="guardUnsavedChanges"
      :saved-data="initialValues"
      :changed-data="currentValues"
      title="Warning"
      description="You have some unsaved changes on this tab! Save them before switching to another tab."
      confirm-text="Discard Changes"
    />
  </form>
</template>

<script lang="ts" setup>
import { useForm, type TypedSchema } from 'vee-validate';
import { cloneDeep, isEqual } from 'lodash';
import { parseDate, type DateValue } from '@internationalized/date';
import { InfoIcon } from 'lucide-vue-next';
import { Alert, AlertDescription, AlertTitle } from '~/components/ui/alert';
import type {
  AllSystemSettings,
  CampaignUrgency,
  RecruitmentChannelStrategy,
  ThrottlingConfig,
  UrgencyPresetsConfig,
} from '~/client';
import { campaignUrgencyOptions } from '~/constants/recruitment/campaignUrgencyConfig';
import { channelStrategyOptions, getChannelStrategy } from '~/constants/recruitment/channelStrategyConfig';

// Superset of both schemas (create adds project_id). Edit simply leaves project_id unset, so
// one type and one set of fields serve both pages.
export interface CampaignFormValues {
  name?: string;
  urgency_level?: CampaignUrgency;
  channel_strategy?: RecruitmentChannelStrategy;
  selling_points?: string;
  latest_news?: string;
  custom_notes?: string;
  end_date?: string | null;
  target_application_count?: number | null;
  target_assignment_count?: number | null;
  project_id?: string;
}

interface Props {
  initialValues?: Partial<CampaignFormValues>;
  isSaving?: boolean;
  submitLabel: string;
  guardUnsavedChanges?: boolean;
  disableSubmitWhenPristine?: boolean;
  onSubmit: (values: CampaignFormValues) => Promise<void>;
  urgencyPresets?: UrgencyPresetsConfig;
  throttling?: ThrottlingConfig;
  channelMessageCost?: AllSystemSettings['channel_message_cost'];
  validationSchema: TypedSchema;
}

const props = withDefaults(defineProps<Props>(), {
  initialValues: undefined,
  isSaving: false,
  guardUnsavedChanges: false,
  disableSubmitWhenPristine: false,
  urgencyPresets: undefined,
  throttling: undefined,
  channelMessageCost: undefined,
});

const { handleSubmit, values } = useForm<CampaignFormValues>({
  validationSchema: props.validationSchema,
  initialValues: props.initialValues,
});

// DatePicker expects DateValue; schema stores string | null.
const endDateValue = computed<DateValue | undefined>(() => (values.end_date ? parseDate(values.end_date) : undefined));

const selectedUrgencyPreset = computed(() => {
  if (!values.urgency_level || !props.urgencyPresets) return null;
  return props.urgencyPresets[values.urgency_level] ?? null;
});

function targetNumber(raw: number | string | null | undefined): number | null {
  const parsed = toNumberOrNull(raw);
  return parsed !== null && parsed > 0 ? parsed : null;
}

const plan = computed(() => {
  const preset = selectedUrgencyPreset.value;
  const throttling = props.throttling;
  const strategy = values.channel_strategy;
  const costs = props.channelMessageCost;
  if (!preset || !throttling || !strategy || !costs) return null;

  // Without a server-priced cost there is no honest daily reach to promise, so the summary stays hidden.
  const costPerContact = costs[strategy];
  if (!costPerContact) return null;
  const dailyMessageCap = Math.min(preset.daily_cap_per_campaign, throttling.global_daily_hard_cap);

  const applications = targetNumber(values.target_application_count);
  const assignments = targetNumber(values.target_assignment_count);
  const reached: string[] = [];
  if (applications !== null) reached.push(`<strong>${applications.toLocaleString()}</strong> applications`);
  if (assignments !== null) reached.push(`<strong>${assignments.toLocaleString()}</strong> assignments`);

  const endDate = values.end_date ? formatUTCDateString(values.end_date, 'MM/dd/yyyy') : null;
  const stopClauses: string[] = [];
  if (reached.length === 2) stopClauses.push(`either ${reached[0]} or ${reached[1]} is reached`);
  else if (reached.length === 1) stopClauses.push(`${reached[0]} is reached`);
  if (endDate) stopClauses.push(`the end date <strong>${endDate}</strong> passes`);
  stopClauses.push('the project is completed');

  return {
    peoplePerDay: Math.floor(dailyMessageCap / costPerContact),
    costPerContact,
    dailyMessageCap,
    touchPhrase: getChannelStrategy(strategy).touchPhrase,
    intervalHours: preset.interval_hours,
    exhaustionThreshold: throttling.project_exhaustion_threshold,
    exhaustedIntervalDays: throttling.exhausted_send_interval_days,
    // Semicolons, not commas: a target clause can itself contain "or", which comma-joining would blur.
    stopSentence:
      stopClauses.length > 1
        ? `Pauses itself as soon as any of these happens: ${stopClauses.join('; ')}.`
        : `Pauses itself when ${stopClauses[0]}.`,
    smsDailyHardCap: strategy !== 'email_only' ? throttling.sms_daily_hard_cap : null,
  };
});

// vee-validate exposes `values` as a reactive Proxy that lodash isEqual does not compare reliably
// against a plain object, so compare a snapshot. Normalize it the way the submit payload does, or a
// masked "1,000" against the stored 1000 counts as an unsaved change.
const currentValues = computed<CampaignFormValues>(() => {
  const snapshot = cloneDeep(values);
  return {
    ...snapshot,
    name: snapshot.name ?? '',
    selling_points: snapshot.selling_points ?? '',
    latest_news: snapshot.latest_news ?? '',
    custom_notes: snapshot.custom_notes ?? '',
    end_date: snapshot.end_date || null,
    target_application_count: toNumberOrNull(snapshot.target_application_count),
    target_assignment_count: toNumberOrNull(snapshot.target_assignment_count),
  };
});

// Drive both the NavigationGuard and the disabled Save button from the SAME comparison
// so they always agree on "no changes".
const isUnchanged = computed(() => isEqual(props.initialValues, currentValues.value));
const isSubmitDisabled = computed(() => props.disableSubmitWhenPristine && isUnchanged.value);

const onFormSubmit = handleSubmit(async (formValues) => {
  try {
    await props.onSubmit(formValues);
  } catch {
    // Error toast is surfaced by the mutation's onError; keep form state so the user can retry.
  }
});
</script>
