import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { campaignUrgencyValues } from '~/constants/recruitment/campaignUrgencyConfig';
import { channelStrategyValues } from '~/constants/recruitment/channelStrategyConfig';

export const campaignUpdateSchemaObject = {
  name: z
    .string({ message: 'Campaign name is required' })
    .trim()
    .nonempty({ message: 'Campaign name is required' })
    .max(255, { message: 'Campaign name must be at most 255 characters long' }),
  urgency_level: z.enum(campaignUrgencyValues, {
    message: 'Urgency level is required',
  }),
  channel_strategy: z.enum(channelStrategyValues, {
    message: 'Channel strategy is required',
  }),
  selling_points: z.string().max(5000, { message: 'Must be at most 5000 characters' }).default(''),
  latest_news: z.string().max(5000, { message: 'Must be at most 5000 characters' }).default(''),
  custom_notes: z.string().max(5000, { message: 'Must be at most 5000 characters' }).default(''),
  end_date: z.string().optional().nullable(),
  target_application_count: z.preprocess(
    (val) => (val === '' || val === null || val === undefined ? null : Number(String(val).replaceAll(',', ''))),
    z
      .number()
      .int({ message: 'Must be a whole number' })
      .min(1, { message: 'Must be at least 1' })
      .max(100000, { message: 'Must be at most 100000' })
      .nullable()
  ),
  target_assignment_count: z.preprocess(
    (val) => (val === '' || val === null || val === undefined ? null : Number(String(val).replaceAll(',', ''))),
    z
      .number()
      .int({ message: 'Must be a whole number' })
      .min(1, { message: 'Must be at least 1' })
      .max(100000, { message: 'Must be at most 100000' })
      .nullable()
  ),
};

export const formSchema = toTypedSchema(z.object(campaignUpdateSchemaObject));
